class Person:
    def __init__(self, name):
        self.name = name

    def walk(self, to):
        print(self.name, 'is walking to', to)


class Student(Person):
    def __init__(self, name):
        # 调用父类的构造函数
        super().__init__(name)

    def go_school(self):
        # 调用父类的方法
        super().walk(to='school')

    def go_home(self):
        # 调用父类的方法
        super().walk(to='home')


obj = Student('John')
obj.go_school()
obj.go_home()

# 输出:
# John is walking to school
# John is walking to home
